392: pub unsafe extern "C" fn liq_image_set_importance_map(img: &mut liq_image, importance_map: *mut u8, buffer_size: usize, ownership: liq_ownership) -> liq_error {
393:     if bad_object!(img, LIQ_IMAGE_MAGIC) { return Error::InvalidPointer; }
394:     let free_fn = img.c_api_free;
395:     let img = &mut img.inner;
396: 
397:     if buffer_size == 0 || liq_received_invalid_pointer(importance_map) { return Error::InvalidPointer; }
398:     let required_size = img.width() * img.height();
399:     if buffer_size < required_size {
400:         return Error::BufferTooSmall;
401:     }
402: 
403:     let importance_map_slice = slice::from_raw_parts(importance_map, required_size);
404:     if ownership == liq_ownership::LIQ_COPY_PIXELS {
405:         img.set_importance_map(importance_map_slice).err().unwrap_or(LIQ_OK)
406:     } else if ownership == liq_ownership::LIQ_OWN_PIXELS {
407:         let copy: Box<[u8]> = importance_map_slice.into();
408:         free_fn(importance_map.cast());
409:         img.set_importance_map(copy).err().unwrap_or(LIQ_OK);
410:         LIQ_OK
411:     } else {
412:         Error::Unsupported
413:     }
414: }
