604: pub(crate) fn check_image_size(attr: &liq_attr, width: u32, height: u32) -> bool {
605:     if bad_object!(attr, LIQ_ATTR_MAGIC) { return false; }
606: 
607:     if width == 0 || height == 0 {
608:         return false;
609:     }
610: 
611:     if width as usize > c_int::MAX as usize / mem::size_of::<liq_color>() / height as usize ||
612:        width as usize > c_int::MAX as usize / 16 / mem::size_of::<f32>() ||
613:        height as usize > c_int::MAX as usize / mem::size_of::<usize>()
614:     {
615:         return false;
616:     }
617:     true
618: }
