    if liq_received_invalid_pointer(entries.cast()) { return Error::InvalidPointer; }

    let entries = slice::from_raw_parts(entries, num_entries);

    input_hist.add_colors(entries, gamma).err().unwrap_or(LIQ_OK)
}

