344: fn sort_palette(attr: &Attributes, palette: &mut PalF) {
345:     let last_index_transparent = attr.last_index_transparent;
346: 
347:     let mut tmp: ArrayVec<_, { MAX_COLORS }> = palette.iter_mut().map(|(c, p)| (*c, *p)).collect();
348:     tmp.sort_by_key(|(color, pop)| {
349:         let trns = !color.is_fully_opaque();
350:         (trns == last_index_transparent, Reverse(OrdFloat::new(pop.popularity())))
351:     });
352:     palette.iter_mut().zip(tmp).for_each(|((dcol, dpop), (scol, spop))| {
353:         *dcol = scol;
354:         *dpop = spop;
355:     });
356: 
357:     if last_index_transparent {
358:         let alpha_index = palette.as_slice().iter().enumerate()
359:             .filter(|(_, c)| !c.is_fully_opaque())
360:             .min_by_key(|(_, c)| OrdFloat::new(c.a))
361:             .map(|(i, _)| i);
362:         if let Some(alpha_index) = alpha_index {
363:             let last_index = palette.as_slice().len() - 1;
364:             palette.swap(last_index, alpha_index);
365:         }
366:     } else {
367:         let num_transparent = palette.as_slice().iter().enumerate().rev()
368:             .find(|(_, c)| !c.is_fully_opaque())
369:             .map(|(i, _)| i + 1); // num entries, not index
370:         if let Some(num_transparent) = num_transparent {
371:             attr.verbose_print(format!("  eliminated opaque tRNS-chunk entries...{} entr{} transparent", num_transparent, if num_transparent == 1 { "y" } else { "ies" }));
372:         }
373:     }
374: }
